import KitData from "./item-kit.mjs";

const { ArrayField, NumberField, SchemaField, StringField } = foundry.data.fields;

/**
 * Item type "trait": a Skills & Powers trait or disadvantage (Player's Option: Skills & Powers, Tables 46 and 47;
 * generated by tools/build-trait-data.py). `cost`: a trait's character points; `points`: a disadvantage's moderate /
 * severe points (severe null: moderate only), `severity` the one taken. `race`: racial adjustments ({ race, delta }:
 * a trait costs `delta` more, a disadvantage gives `delta` more). `modifiers`: kit-modifier format (applied with the
 * kit's in CharacterData). Owner's ruling: no character points; traits are balanced by disadvantages (character sheet).
 */
export default class TraitData extends foundry.abstract.TypeDataModel {
  static defineSchema() {
    return {
      identifier: new StringField({ required: true, blank: true, initial: "" }),
      kind: new StringField({ required: true, initial: "trait", choices: ["trait", "disadvantage"] }),
      cost: new NumberField({ integer: true, min: 0, nullable: true, initial: null }),
      points: new SchemaField({
        moderate: new NumberField({ integer: true, min: 0, nullable: true, initial: null }),
        severe: new NumberField({ integer: true, min: 0, nullable: true, initial: null })
      }),
      severity: new StringField({ required: true, initial: "moderate", choices: ["moderate", "severe"] }),
      race: new ArrayField(new SchemaField({ race: new StringField({ initial: "" }), delta: new NumberField({ integer: true, initial: 0 }) })),
      modifiers: KitData.defineSchema().modifiers,
      source: new StringField({ initial: "" }),
      url: new StringField({ initial: "" }),
      notes: new StringField({ initial: "" })
    };
  }

  /** Points for a race: a trait's cost or a disadvantage's points (severity taken), with the racial adjustment. */
  valueFor(raceId = "") {
    const delta = this.race.filter(r => r.race === raceId).reduce((n, r) => n + r.delta, 0);
    if (this.kind === "trait") return Math.max((this.cost ?? 0) + delta, 0);
    const base = this.severity === "severe" && this.points.severe !== null ? this.points.severe : (this.points.moderate ?? 0);
    return Math.max(base + delta, 0);
  }
}
